import React, { useState, useEffect } from 'react';
import { supabaseService } from '../../services/supabaseService';
import Icon from '../AppIcon';
import { cn } from '../../utils/cn';

const RecordedSessionsList = ({ onWatch }) => {
    const [recordings, setRecordings] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchRecordings = async () => {
            try {
                const data = await supabaseService.getRecordedSessions();
                setRecordings(data);
            } catch (err) {
                console.error("Error fetching recordings:", err);
            } finally {
                setLoading(false);
            }
        };
        fetchRecordings();
    }, []);

    if (loading) {
        return (
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 animate-pulse">
                {[1, 2, 3].map(i => (
                    <div key={i} className="h-48 bg-slate-800/50 rounded-3xl border border-slate-700/50" />
                ))}
            </div>
        );
    }

    if (recordings.length === 0) {
        return (
            <div className="text-center py-20 bg-slate-900/50 rounded-[3rem] border-2 border-dashed border-slate-800">
                <Icon name="PlayCircle" size={48} className="mx-auto text-slate-700 mb-4" />
                <h3 className="text-slate-400 font-bold">No recordings available yet</h3>
                <p className="text-slate-600 text-sm">Once a session is recorded, it will appear here.</p>
            </div>
        );
    }

    return (
        <div className="flex gap-6 md:gap-8 overflow-x-auto pb-4 snap-x snap-mandatory scrollbar-hide pl-1 lg:pl-0 lg:grid lg:grid-cols-3 lg:gap-8 lg:overflow-visible lg:pb-0">
            {recordings.map((recording) => (
                <div 
                    key={recording.id}
                    className="group relative bg-slate-900 rounded-2xl lg:rounded-[2.5rem] overflow-hidden border border-white/5 hover:border-primary/50 transition-all duration-500 shadow-2xl hover:shadow-primary/20 shrink-0 w-[80vw] sm:w-[60vw] snap-center lg:w-auto lg:shrink lg:snap-align-none"
                >
                    {/* Video Placeholder/Thumbnail */}
                    <div className="h-48 bg-gradient-to-br from-slate-800 to-black flex items-center justify-center relative overflow-hidden">
                        <Icon name="Video" size={40} className="text-slate-700 group-hover:text-primary/50 transition-colors duration-500" />
                        <div className="absolute inset-0 bg-primary/10 opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
                        
                        {/* Play Overlay */}
                        <button 
                            onClick={() => onWatch(recording)}
                            className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-all duration-500 transform translate-y-4 group-hover:translate-y-0"
                        >
                            <div className="w-16 h-16 bg-primary rounded-full flex items-center justify-center shadow-2xl scale-90 group-hover:scale-100 transition-transform duration-500">
                                <Icon name="Play" size={24} className="text-white fill-current ml-1" />
                            </div>
                        </button>
                    </div>

                    <div className="p-6">
                        <div className="flex items-center justify-between mb-2">
                            <span className="text-[10px] font-black tracking-widest text-primary uppercase bg-primary/10 px-3 py-1 rounded-full border border-primary/20">
                                Session Replay
                            </span>
                            <span className="text-[10px] text-slate-500 font-bold uppercase tracking-tighter">
                                {new Date(recording.created_at).toLocaleDateString()}
                            </span>
                        </div>
                        <h4 className="text-white font-bold text-lg line-clamp-1 mb-1">
                            {recording.name}
                        </h4>
                        <p className="text-slate-500 text-xs mb-4 line-clamp-2">
                            Watch the full archive of this brainstorming and collaborative session.
                        </p>
                        
                        <button 
                            onClick={() => onWatch(recording)}
                            className="w-full py-3 bg-white/5 hover:bg-primary text-white font-black text-xs uppercase tracking-widest rounded-2xl transition-all border border-white/5 hover:border-primary active:scale-95"
                        >
                            Watch Recording
                        </button>
                    </div>
                </div>
            ))}
        </div>
    );
};

export default RecordedSessionsList;
