import React, { useState, useRef } from 'react';
import { useDispatch } from 'react-redux';
import { loginStart, loginSuccess, loginFailure } from '../../../store/authSlice';
import { supabaseService } from '../../../services/supabaseService';
import Modal from '../../../components/ui/Modal';
import Button from '../../../components/ui/Button';
import Input from '../../../components/ui/Input';
import Icon from '../../../components/AppIcon';
import { useToast } from '../../../contexts/ToastContext';
import { Turnstile } from '@marsidev/react-turnstile';

const AcademyAuthModal = ({ isOpen, onClose, onAuthSuccess, prefilledName }) => {
    const { addToast } = useToast();
    const dispatch = useDispatch();
    const [mode, setMode] = useState('login');
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [name, setName] = useState('');
    const [gender, setGender] = useState('');
    const [phone, setPhone] = useState('');
    const [ageRange, setAgeRange] = useState('');
    const [demography, setDemography] = useState('');
    const [country, setCountry] = useState('');
    const [confirm, setConfirm] = useState('');
    const [error, setError] = useState('');
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [captchaToken, setCaptchaToken] = useState(null);
    const turnstileRef = useRef(null);

    React.useEffect(() => {
        if (isOpen && prefilledName && !name) {
            setName(prefilledName);
        }
    }, [isOpen, prefilledName]);

    const resetForm = () => {
        setEmail('');
        setPassword('');
        setName(prefilledName || '');
        setGender('');
        setPhone('');
        setAgeRange('');
        setDemography('');
        setCountry('');
        setConfirm('');
        setError('');
    };

    const switchMode = (newMode) => {
        resetForm();
        setMode(newMode);
    };

    const handleLogin = async (e) => {
        e.preventDefault();
        setError('');
        if (!email || !password) return setError('Email and password are required');
        if (!captchaToken) return setError('Please complete the security check');
        setIsSubmitting(true);
        dispatch(loginStart());
        try {
            const res = await supabaseService.login(email, password, captchaToken);
            if (res.user) {
                dispatch(loginSuccess({
                    token: res.session?.access_token || '',
                    user: res.user,
                    role: 'user'
                }));
                addToast('Welcome back!', 'success');
                onAuthSuccess(res.user);
            }
        } catch (err) {
            const msg = err.message || 'Login failed';
            setError(msg);
            dispatch(loginFailure(msg));
            if (turnstileRef.current) {
                turnstileRef.current.reset();
                setCaptchaToken(null);
            }
        } finally {
            setIsSubmitting(false);
        }
    };

    const handleSignup = async (e) => {
        e.preventDefault();
        setError('');
        if (!name || !email) return setError('Name and email are required');
        if (!gender || !phone || !ageRange || !demography || !country) return setError('Please fill in all demographic fields to continue');
        if (!password || !confirm) return setError('Password is required');
        if (password.length < 6) return setError('Password must be at least 6 characters');
        if (password !== confirm) return setError('Passwords do not match');
        if (!captchaToken) return setError('Please complete the security check');
        setIsSubmitting(true);
        dispatch(loginStart());
        try {
            const extraData = { 
                gender: gender,
                phone: phone, 
                age_range: ageRange, 
                demography: demography, 
                country: country 
            };
            const res = await supabaseService.signup(email, password, name, captchaToken, null, extraData);
            if (res.user) {
                if (res.session) {
                    dispatch(loginSuccess({
                        token: res.session.access_token,
                        user: res.user,
                        role: 'user'
                    }));
                    addToast('Account created! Let\'s finish your enrollment.', 'success');
                    onAuthSuccess(res.user);
                } else {
                    setMode('verify');
                }
            }
        } catch (err) {
            const msg = err.message || 'Signup failed';
            setError(msg);
            dispatch(loginFailure(msg));
            if (turnstileRef.current) {
                turnstileRef.current.reset();
                setCaptchaToken(null);
            }
        } finally {
            setIsSubmitting(false);
        }
    };

    if (mode === 'verify') {
        return (
            <Modal isOpen={isOpen} onClose={onClose} title="Check Your Email" size="sm">
                <div className="text-center py-6">
                    <div className="w-16 h-16 bg-emerald-500/10 rounded-full flex items-center justify-center mx-auto mb-4">
                        <Icon name="Mail" size={32} className="text-emerald-500" />
                    </div>
                    <h3 className="text-lg font-bold mb-2">Verify Your Email</h3>
                    <p className="text-sm text-muted-foreground mb-6">
                        We sent a verification link to <strong>{email}</strong>. Check your inbox and click the link to continue.
                    </p>
                    <Button variant="outline" onClick={() => switchMode('login')} className="w-full">
                        Back to Login
                    </Button>
                </div>
            </Modal>
        );
    }

    return (
        <Modal
            isOpen={isOpen}
            onClose={onClose}
            title={mode === 'login' ? 'Sign In to Continue' : 'Create Account'}
            size="sm"
        >
            <div className="space-y-4">
                {error && (
                    <div className="p-3 bg-destructive/10 border border-destructive/20 rounded-xl text-sm text-destructive">
                        {error}
                    </div>
                )}

                {mode === 'login' ? (
                    <form onSubmit={handleLogin} className="space-y-4">
                        <Input
                            label="Email"
                            type="email"
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                            placeholder="you@example.com"
                            required
                        />
                        <Input
                            label="Password"
                            type="password"
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            placeholder="Enter your password"
                            required
                        />
                        <div className="flex justify-center items-center my-4 w-full max-w-full overflow-hidden rounded-xl border border-gray-100 dark:border-gray-700 p-1.5 sm:p-2 bg-gray-50 dark:bg-gray-900/50 min-h-[65px] [&>div]:scale-[0.85] min-[380px]:[&>div]:scale-100 [&>div]:origin-center">
                            <Turnstile
                                ref={turnstileRef}
                                siteKey={import.meta.env.VITE_TURNSTILE_SITE_KEY}
                                onSuccess={(token) => setCaptchaToken(token)}
                                onError={() => setError('Security check failed. Please refresh.')}
                                theme="auto"
                            />
                        </div>
                        <Button
                            type="submit"
                            loading={isSubmitting}
                            className="w-full py-3 font-bold rounded-xl"
                        >
                            Sign In
                        </Button>
                        <p className="text-center text-sm text-muted-foreground">
                            Don't have an account?{' '}
                            <button type="button" onClick={() => switchMode('signup')} className="text-primary font-bold hover:underline">
                                Sign Up Free
                            </button>
                        </p>
                    </form>
                ) : (
                    <form onSubmit={handleSignup} className="space-y-4">
                        <Input
                            label="Full Name"
                            value={name}
                            onChange={(e) => setName(e.target.value)}
                            placeholder="Enter your full name"
                            required
                        />
                        <Input
                            label="Email"
                            type="email"
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                            placeholder="you@example.com"
                            required
                        />

                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-sm font-semibold mb-2 text-foreground">Gender</label>
                                <select 
                                    value={gender} 
                                    onChange={(e) => setGender(e.target.value)}
                                    required
                                    className="w-full flex h-10 rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
                                >
                                    <option value="" disabled>Select</option>
                                    <option value="Male">Male</option>
                                    <option value="Female">Female</option>
                                    <option value="Non-binary">Non-binary</option>
                                    <option value="Prefer not to say">Prefer not to say</option>
                                </select>
                            </div>
                            <div>
                                <label className="block text-sm font-semibold mb-2 text-foreground">Age Range</label>
                                <select 
                                    value={ageRange} 
                                    onChange={(e) => setAgeRange(e.target.value)}
                                    required
                                    className="w-full flex h-10 rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
                                >
                                    <option value="" disabled>Select</option>
                                    <option value="Under 18">Under 18</option>
                                    <option value="18-24">18-24</option>
                                    <option value="25-34">25-34</option>
                                    <option value="35-44">35-44</option>
                                    <option value="45-54">45-54</option>
                                    <option value="55+">55+</option>
                                </select>
                            </div>
                        </div>

                        <Input
                            label="Phone Number"
                            type="tel"
                            value={phone}
                            onChange={(e) => setPhone(e.target.value)}
                            placeholder="+1 234 567 8900"
                            required
                        />

                        <div className="grid grid-cols-2 gap-4">
                            <Input
                                label="Occupation"
                                value={demography}
                                onChange={(e) => setDemography(e.target.value)}
                                placeholder="e.g. Student"
                                required
                            />
                            <Input
                                label="Country"
                                value={country}
                                onChange={(e) => setCountry(e.target.value)}
                                placeholder="e.g. Nigeria"
                                required
                            />
                        </div>
                        <Input
                            label="Password"
                            type="password"
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            placeholder="Min. 6 characters"
                            required
                        />
                        <Input
                            label="Confirm Password"
                            type="password"
                            value={confirm}
                            onChange={(e) => setConfirm(e.target.value)}
                            placeholder="Repeat your password"
                            required
                        />
                        <div className="flex justify-center items-center my-4 w-full max-w-full overflow-hidden rounded-xl border border-gray-100 dark:border-gray-700 p-1.5 sm:p-2 bg-gray-50 dark:bg-gray-900/50 min-h-[65px] [&>div]:scale-[0.85] min-[380px]:[&>div]:scale-100 [&>div]:origin-center">
                            <Turnstile
                                ref={turnstileRef}
                                siteKey={import.meta.env.VITE_TURNSTILE_SITE_KEY}
                                onSuccess={(token) => setCaptchaToken(token)}
                                onError={() => setError('Security check failed. Please refresh.')}
                                theme="auto"
                            />
                        </div>
                        <Button
                            type="submit"
                            loading={isSubmitting}
                            className="w-full py-3 font-bold rounded-xl"
                        >
                            Create Account
                        </Button>
                        <p className="text-center text-sm text-muted-foreground">
                            Already have an account?{' '}
                            <button type="button" onClick={() => switchMode('login')} className="text-primary font-bold hover:underline">
                                Sign In
                            </button>
                        </p>
                    </form>
                )}
            </div>
        </Modal>
    );
};

export default AcademyAuthModal;
